import { useQuery } from "@tanstack/react-query";
import { createFileRoute, Link } from "@tanstack/react-router";

import { Badge } from "../components/ui/badge";
import { Button } from "../components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "../components/ui/card";
import { getTreaty } from "./api.$";

export const Route = createFileRoute("/")({
  component: HomePage,
  loader: async () => {
    const response = await getTreaty().health.get();
    return { apiStatus: response.data?.status ?? "unavailable" };
  },
});

function HomePage() {
  const { apiStatus } = Route.useLoaderData();
  const health = useQuery({
    queryFn: async () => (await getTreaty().health.get()).data,
    queryKey: ["api", "health"],
  });
  const status = health.data?.status ?? apiStatus;

  return (
    <section className="mx-auto grid max-w-6xl gap-12 px-5 py-14 sm:px-8 sm:py-20 lg:grid-cols-[1.1fr_0.9fr] lg:items-center lg:gap-20">
      <div>
        <Badge>M0 / compatibility spike</Badge>
        <h1 className="mt-6 max-w-3xl font-display text-5xl font-semibold leading-[0.98] tracking-[-0.055em] text-white sm:text-7xl">
          One calm place for every identity.
        </h1>
        <p className="mt-7 max-w-xl text-lg leading-8 text-white/60 sm:text-xl">
          Mikan is an identity control plane for people, applications, permissions, and the
          protocols that connect them.
        </p>
        <div className="mt-9 flex flex-col gap-3 sm:flex-row">
          <Link to="/sign-in">
            <Button className="w-full sm:w-auto">Open the control plane</Button>
          </Link>
          <a href="/api/health">
            <Button className="w-full sm:w-auto" variant="outline">
              Inspect API health
            </Button>
          </a>
        </div>
      </div>
      <Card className="border-white/10 bg-white/[0.06]">
        <CardHeader>
          <p className="text-xs font-medium uppercase tracking-[0.18em] text-white/40">
