display.text:
import { useForm } from "@tanstack/react-form";
import { createFileRoute, Link } from "@tanstack/react-router";
import { useState } from "react";

import { Button } from "../components/ui/button";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "../components/ui/card";
import { Input } from "../components/ui/input";

export const Route = createFileRoute("/sign-in")({ component: SignInPage });

function SignInPage() {
  const [message, setMessage] = useState<string>();
  const form = useForm({
    defaultValues: { email: "", password: "" },
    onSubmit: async ({ value }) => {
      const response = await fetch("/api/auth/sign-in/email", {
        body: JSON.stringify(value),
        credentials: "include",
        headers: { "content-type": "application/json" },
        method: "POST",
      });
      setMessage(response.ok ? "Signed in." : "The credentials could not be verified.");
    },
  });

  return (
    <section className="mx-auto max-w-xl px-5 py-14 sm:px-8 sm:py-20">
      <p className="text-sm font-medium uppercase tracking-[0.18em] text-[var(--tangerine)]">
        Welcome back
      </p>
      <h1 className="mt-5 font-display text-5xl font-semibold leading-none tracking-[-0.05em] text-white">
        Your identity, with fewer sharp edges.
      </h1>
      <Card className="mt-10 border-white/10 bg-white/[0.06]">
        <CardHeader>
          <CardTitle className="text-2xl text-white">Sign in</CardTitle>
          <CardDescription className="text-white/50">
            M0 uses Better Auth email/password as its first protocol probe.
          </CardDescription>
        </CardHeader>
        <CardContent>
          <form
            className="space-y-5"
            onSubmit={(event) => {
              event.preventDefault();
              void form.handleSubmit();
            }}
          >
            <form.Field name="email">
              {(field) => (
                <label className="block space-y-2 text-sm text-white/65" htmlFor="email">
                  Email
                  <Input
                    id="email"
                    autoComplete="email"
                    onChange={(event) => field.handleChange(event.target.value)}
                    value={field.state.value}
                  />
                </label>
              )}
            </form.Field>
            <form.Field name="password">
              {(field) => (
                <label className="block space-y-2 text-sm text-white/65" htmlFor="password">
                  Password
                  <Input
                    id="password"
                    autoComplete="current-password"
                    onChange={(event) => field.handleChange(event.target.value)}
                    type="password"
                    value={field.state.value}
                  />
                </label>
              )}
            </form.Field>
            <Button className="w-full" type="submit">
              Continue
            </Button>
            {message ? <p className="text-sm text-[var(--tangerine)]">{message}</p> : null}
          </form>
          <Link className="mt-5 inline-block text-sm text-white/45 hover:text-white" to="/">
            Back to overview
          </Link>
        </CardContent>
      </Card>
    </section>
  );
}

