import { Link as KumoLink, LinkProvider, type LinkComponentProps } from "@cloudflare/kumo";
import type { QueryClient } from "@tanstack/react-query";
import { QueryClientProvider } from "@tanstack/react-query";
import {
  createRootRouteWithContext,
  HeadContent,
  Link as RouterLink,
  Outlet,
  Scripts,
} from "@tanstack/react-router";
import { forwardRef, type ReactNode } from "react";

import "../styles/app.css";

export const Route = createRootRouteWithContext<{ queryClient: QueryClient }>()({
  head: () => ({
    meta: [
      { charSet: "utf-8" },
      { name: "viewport", content: "width=device-width, initial-scale=1" },
      { name: "description", content: "Mikan identity control plane" },
    ],
    title: "Mikan | identity control plane",
  }),
  component: RootComponent,
});

function RootComponent() {
  const { queryClient } = Route.useRouteContext();

  return (
    <RootDocument>
      <QueryClientProvider client={queryClient}>
        <LinkProvider component={AppLink}>
          <div className="min-h-screen bg-kumo-canvas text-kumo-default">
            <header className="border-b border-kumo-line">
              <div className="mx-auto flex max-w-6xl items-center justify-between px-5 py-5 sm:px-8">
                <RouterLink className="inline-flex items-center gap-3" to="/">
                  <span className="grid size-9 place-items-center rounded-lg bg-[var(--tangerine)] font-bold text-[var(--ink)]">
                    M
                  </span>
                  <span className="font-display text-lg font-semibold tracking-tight">mikan</span>
                </RouterLink>
                <nav className="flex items-center gap-1 text-sm">
                  <KumoLink className="rounded-md px-3 py-2" href="/consent" variant="plain">
                    Consent
                  </KumoLink>
                  <KumoLink className="rounded-md px-3 py-2" href="/sign-in" variant="plain">
                    Sign in
                  </KumoLink>
                </nav>
              </div>
            </header>
            <main>
              <Outlet />
            </main>
          </div>
        </LinkProvider>
      </QueryClientProvider>
    </RootDocument>
  );
}

const AppLink = forwardRef<HTMLAnchorElement, LinkComponentProps>(function AppLink(
  { href, ...props },
  ref,
) {
  if (!href || href.startsWith("#") || href.startsWith("/api/") || isExternalHref(href)) {
    return <a ref={ref} href={href} {...props} />;
  }

  return <RouterLink ref={ref} to={href} {...props} />;
});

function isExternalHref(href: string) {
  return /^(?:[a-z][a-z\d+.-]*:|\/\/)/i.test(href);
}

function RootDocument({ children }: Readonly<{ children: ReactNode }>) {
  return (
    <html data-mode="dark" lang="en">
      <head>
        <HeadContent />
      </head>
      <body>
        {children}
        <Scripts />
      </body>
    </html>
  );
}

