import { Badge, LayerCard, LinkButton } from "@cloudflare/kumo";
import { useQuery } from "@tanstack/react-query";
import { createFileRoute } from "@tanstack/react-router";

import { getTreaty } from "./api.$";

export const Route = createFileRoute("/")({
  component: HomePage,
  loader: async () => {
    const response = await getTreaty().health.get();
    return { apiStatus: response.data?.status ?? "unavailable" };
  },
});

function HomePage() {
  const { apiStatus } = Route.useLoaderData();
  const health = useQuery({
    queryFn: async () => (await getTreaty().health.get()).data,
    queryKey: ["api", "health"],
  });
  const status = health.data?.status ?? apiStatus;

  return (
    <section className="mx-auto grid max-w-6xl gap-12 px-5 py-14 sm:px-8 sm:py-20 lg:grid-cols-[1.1fr_0.9fr] lg:items-center lg:gap-20">
      <div>
        <Badge variant="orange">M0 / compatibility spike</Badge>
        <h1 className="mt-6 max-w-3xl font-display text-5xl font-semibold leading-[0.98] tracking-[-0.055em] text-kumo-strong sm:text-7xl">
          One calm place for every identity.
        </h1>
        <p className="mt-7 max-w-xl text-lg leading-8 text-kumo-subtle sm:text-xl">
          Mikan is an identity control plane for people, applications, permissions, and the
          protocols that connect them.
        </p>
        <div className="mt-9 flex flex-col gap-3 sm:flex-row">
          <LinkButton className="w-full sm:w-auto" href="/sign-in" size="lg" variant="primary">
            Open the control plane
          </LinkButton>
          <LinkButton className="w-full sm:w-auto" href="/api/health" size="lg" variant="outline">
            Inspect API health
          </LinkButton>
        </div>
      </div>
      <LayerCard className="border-kumo-line bg-kumo-elevated p-6">
        <p className="text-xs font-medium uppercase tracking-[0.18em] text-kumo-subtle">
          Runtime signal
        </p>
        <h2 className="mt-3 font-display text-3xl font-semibold tracking-tight text-kumo-strong">
          The edge is awake.
        </h2>
        <div className="mt-6 flex items-center justify-between rounded-lg border border-kumo-hairline bg-kumo-recessed p-4">
          <span className="text-sm text-kumo-subtle">Elysia /api/health</span>
          <Badge appearance="dot" variant={status === "ok" ? "success" : "warning"}>
            {status}
          </Badge>
        </div>
        <dl className="mt-6 grid grid-cols-2 gap-4 text-sm">
          <div>
            <dt className="text-kumo-subtle">Runtime</dt>
            <dd className="mt-1 text-kumo-default">Workers</dd>
          </div>
          <div>
            <dt className="text-kumo-subtle">Database</dt>
            <dd className="mt-1 text-kumo-default">D1 + Drizzle</dd>
          </div>
        </dl>
      </LayerCard>
    </section>
  );
}

